blocks.text:
powershell.exe -NoProfile -File artifacts\Invoke-ProtectionProbe.ps1 -Phase Run -ExpectedPacketSha256 $env:EXPECTED_PACKET_SHA256 *> "$env:RUNNER_TEMP\system-observation-run.private.log"
if ($LASTEXITCODE -ne 0) { throw 'Run/exit unconfirmed; no retry or kill.' }
Write-Output 'Original process exit receipt recorded; capture success not implied.'

$evidenceRoot = 'C:\ProgramData\RescueSessionIOPrereq-20261104-evidence'
$exitProof = [IO.File]::ReadAllText((Join-Path $evidenceRoot 'exit.json')) | ConvertFrom-Json
if ($exitProof.consumed -isnot [bool] -or $exitProof.consumed -ne $true -or
    $exitProof.processExitConfirmed -isnot [bool] -or $exitProof.processExitConfirmed -ne $true -or
    $exitProof.proof.processExitCode -ne 0 -or $exitProof.proof.serviceWin32Exit -ne 0 -or
    $exitProof.proof.serviceSpecificExit -ne 0 -or
    $exitProof.proof.binding.manifestSha256 -cne $env:EXPECTED_PACKET_SHA256 -or
    $exitProof.proof.binding.service -cne 'RescueSessionIOPrereq-20261104') { throw 'Original process/service exit did not confirm observation persistence.' }
$rawPath = Join-Path $evidenceRoot 'subject.json'
if ((Get-Item -LiteralPath $rawPath).Length -gt 262144) { throw 'Private report exceeds bound.' }
$raw = [IO.File]::ReadAllText($rawPath, [Text.UTF8Encoding]::new($false, $true))
$public = $raw | & .\artifacts\scm-token-observer.exe --summary 2>$null
$summaryExit = $LASTEXITCODE
$publicText = $public -join "`n"
if ([Text.Encoding]::UTF8.GetByteCount($publicText) -gt 65536) { throw 'Public summary exceeds bound.' }
$summary = $publicText | ConvertFrom-Json
if ($summary.report_sha256 -cne $exitProof.reportSha256 -or
    $summary.native_acceptance -cne 'NOT_EVALUATED' -or $summary.product_gate -cne 'CLOSED') { throw 'Original report digest/scope mismatch; no observation publication.' }
if ($public) { Write-Output $public; Add-Content -LiteralPath $env:GITHUB_STEP_SUMMARY -Value $public -Encoding UTF8 }
if ($summaryExit -ne 0) { throw 'Incomplete observation; native acceptance NOT_EVALUATED and gate CLOSED.' }
